1	"use client";
2	
3	/**
4	 * The interactive half of the marketing /mods homepage's game catalogue —
5	 * split out of GameCatalogueGrid.tsx (a Server Component, which does the
6	 * real per-game accent-color sampling) because search + carousel state both
7	 * need client JS. This component receives fully-resolved, already-real data
8	 * (name, poster, accent, href — no placeholders) and only handles two
9	 * interactions:
10	 *
11	 *   1. A live client-side search over these exact ~17 families — no
12	 *      round-trip, since the whole list is already in hand and this small a
13	 *      set never needs pagination (contrast StoreBrowser.tsx's own
14	 *      server-side search, which exists precisely because the general mod
15	 *      catalog is 30k+ rows and can't live in the client at once).
16	 *   2. A single-row sliding carousel instead of the old wrapping grid —
17	 *      plain CSS scroll-snap (`overflow-x-auto` + `snap-x`) rather than a
18	 *      new dependency: this codebase has no carousel library (checked
19	 *      package.json) and already ships this exact pattern for
20	 *      GameShowcaseCarousel.tsx's hero row. Native scroll-snap gives real
21	 *      touch/trackpad swipe for free; the arrow buttons and a light
22	 *      pointer-drag handler (mouse users with neither) are added on top.
23	 */
24	
25	import { useMemo, useRef, useState } from "react";
26	import Link from "next/link";
27	import { IconArrow, IconSearch } from "./icons";
28	
29	export type CatalogueItem = {
30	  family: string;
31	  name: string;
32	  count: number;
33	  poster?: string;
34	  accent: string;
35	  href: string;
36	};
37	
38	function prefersReducedMotion() {
39	  return typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
40	}
41	
42	export function GameCatalogueCarousel({ items }: { items: CatalogueItem[] }) {
43	  const [query, setQuery] = useState("");
44	  const trackRef = useRef<HTMLDivElement>(null);
45	
46	  const filtered = useMemo(() => {
47	    const q = query.trim().toLowerCase();
48	    if (!q) return items;
49	    return items.filter((it) => it.name.toLowerCase().includes(q));
50	  }, [items, query]);
51	
52	  function scrollByCard(dir: 1 | -1) {
53	    const track = trackRef.current;
54	    if (!track) return;
55	    const card = track.querySelector<HTMLElement>("[data-card]");
56	    const step = card ? card.offsetWidth + 16 /* gap-4 */ : track.clientWidth * 0.8;
57	    track.scrollBy({ left: dir * step, behavior: prefersReducedMotion() ? "auto" : "smooth" });
58	  }
59	
60	  // Lightweight drag-to-scroll for desktop mouse users (touch/trackpad already
61	  // get real native scrolling from `overflow-x-auto` + `snap-x` with no JS at
62	  // all). Only counts as a "drag" past a small pixel threshold, and when it
63	  // does, the click that would otherwise follow (and navigate a card's Link)
64	  // is swallowed once — same guard GameCoverCarousel.tsx uses for its own
65	  // momentum drag, just without the velocity/spring machinery this static
66	  // catalogue row doesn't need.
67	  const drag = useRef<{ startX: number; startScroll: number; moved: boolean } | null>(null);
68	
69	  function onPointerDown(e: React.PointerEvent<HTMLDivElement>) {
70	    if (e.pointerType === "touch") return;
71	    const track = trackRef.current;
72	    if (!track) return;
73	    drag.current = { startX: e.clientX, startScroll: track.scrollLeft, moved: false };
74	    track.setPointerCapture(e.pointerId);
75	  }
76	  function onPointerMove(e: React.PointerEvent<HTMLDivElement>) {
77	    const st = drag.current;
78	    const track = trackRef.current;
79	    if (!st || !track) return;
80	    const dx = e.clientX - st.startX;
81	    if (Math.abs(dx) > 3) st.moved = true;
82	    track.scrollLeft = st.startScroll - dx;
83	  }
84	  function onPointerUp(e: React.PointerEvent<HTMLDivElement>) {
85	    const st = drag.current;
86	    const track = trackRef.current;
87	    if (st?.moved && track) {
88	      const stop = (ev: Event) => {
89	        ev.preventDefault();
90	        ev.stopPropagation();
91	      };
92	      track.addEventListener("click", stop, { capture: true, once: true });
93	    }
94	    drag.current = null;
95	    track?.releasePointerCapture?.(e.pointerId);
96	  }
97	
98	  return (
99	    <div>
100	      <div className="relative mb-6 max-w-sm">
101	        <IconSearch
102	          className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-[var(--fg-muted)]"
103	          size={16}
104	        />
105	        <input
106	          type="search"
107	          value={query}
108	          onChange={(e) => setQuery(e.target.value)}
109	          placeholder="Search games…"
110	          aria-label="Search games"
111	          className="input w-full pl-9 text-sm"
112	        />
113	      </div>
114	
115	      {filtered.length === 0 ? (
116	        <p className="rounded-2xl border border-white/10 bg-white/[0.02] px-6 py-10 text-center text-sm text-slate-400">
117	          No games match &ldquo;{query}&rdquo;.
118	        </p>
119	      ) : (
120	        <div className="relative">
121	          {/* Arrow controls — hidden on touch-first small screens (swipe instead),
122	              same treatment as GameShowcaseCarousel's own hero row. */}
123	          <div className="pointer-events-none absolute inset-y-0 left-0 right-0 z-20 hidden items-center justify-between sm:flex">
124	            <button
125	              type="button"
126	              aria-label="Scroll games left"
127	              onClick={() => scrollByCard(-1)}
128	              className="pointer-events-auto -ml-3 grid h-10 w-10 place-items-center rounded-full border border-white/10 bg-navy-900/80 text-slate-200 backdrop-blur transition hover:border-brand-500/40 hover:text-white lg:-ml-5"
129	            >
130	              <span className="rotate-180">
131	                <IconArrow size={18} />
132	              </span>
133	            </button>
134	            <button
135	              type="button"
136	              aria-label="Scroll games right"
137	              onClick={() => scrollByCard(1)}
138	              className="pointer-events-auto -mr-3 grid h-10 w-10 place-items-center rounded-full border border-white/10 bg-navy-900/80 text-slate-200 backdrop-blur transition hover:border-brand-500/40 hover:text-white lg:-mr-5"
139	            >
140	              <IconArrow size={18} />
141	            </button>
142	          </div>
143	
144	          <div
145	            ref={trackRef}
146	            onPointerDown={onPointerDown}
147	            onPointerMove={onPointerMove}
148	            onPointerUp={onPointerUp}
149	            onPointerCancel={onPointerUp}
150	            className="flex snap-x snap-mandatory gap-4 overflow-x-auto scroll-smooth pb-4 pt-1 [scrollbar-width:none] motion-reduce:scroll-auto [&::-webkit-scrollbar]:hidden"
151	            style={{ cursor: "grab" }}
152	          >
153	            {filtered.map((it) => (
154	              <Link
155	                key={it.family}
156	                data-card
157	                href={it.href}
158	                draggable={false}
159	                className="group relative flex w-36 shrink-0 snap-start flex-col overflow-hidden rounded-2xl border border-white/10 bg-white/[0.02] transition-all duration-200 hover:-translate-y-1 sm:w-44 lg:w-48"
160	              >
161	                <div className="relative aspect-[3/4] w-full overflow-hidden bg-white/[0.04]">
162	                  {it.poster ? (
163	                    // eslint-disable-next-line @next/next/no-img-element
164	                    <img
165	                      src={`/games/art/${it.poster}_poster.jpg`}
166	                      alt={it.name}
167	                      loading="lazy"
168	                      draggable={false}
169	                      className="h-full w-full object-cover transition-transform duration-300 group-hover:scale-[1.06]"
170	                    />
171	                  ) : (
172	                    <div className="flex h-full w-full items-center justify-center text-3xl">🎮</div>
173	                  )}
174	                  {/* accent-colored ring, revealed on hover — genuinely sampled per game (inline
175	                      box-shadow, not Tailwind's `ring-*` utility, so this doesn't depend on
176	                      Tailwind's internal --tw-ring-color implementation detail). */}
177	                  <div
178	                    className="pointer-events-none absolute inset-0 rounded-2xl opacity-0 transition-opacity duration-200 group-hover:opacity-100"
179	                    style={{ boxShadow: `inset 0 0 0 2px ${it.accent}` }}
180	                    aria-hidden
181	                  />
182	                  <div className="pointer-events-none absolute inset-x-0 bottom-0 h-2/3 bg-gradient-to-t from-black/90 to-transparent" />
183	                  {/* "Browse mods" reveal — the catalogue framing, not just a poster wall */}
184	                  <div className="pointer-events-none absolute inset-0 flex items-end justify-center pb-3 opacity-0 transition-opacity duration-200 group-hover:opacity-100">
185	                    <span
186	                      className="rounded-full px-3 py-1 text-[11px] font-semibold uppercase tracking-wide text-white"
187	                      style={{ background: it.accent }}
188	                    >
189	                      Browse mods →
190	                    </span>
191	                  </div>
192	                </div>
193	                <div className="p-3">
194	                  <p className="truncate text-sm font-semibold text-white">{it.name}</p>
195	                  <p className="text-[11px] text-slate-400">{it.count.toLocaleString()} mods</p>
196	                </div>
197	              </Link>
198	            ))}
199	          </div>
200	        </div>
201	      )}
202	    </div>
203	  );
204	}
