    await ctx.close();
    return;
  }
  const cx = box.x + box.width / 2;
  const cy = box.y + box.height / 2;
  const urlBefore = page.url();

  // Simulate a REAL mouse click with a few px of jitter, exactly like a human
  // hand produces between mousedown and mouseup - NOT a synthetic .click().
  await page.mouse.move(cx, cy);
  await page.mouse.down();
  await page.mouse.move(cx + 2, cy + 1, { steps: 3 });
  await page.mouse.move(cx + 4, cy + 2, { steps: 3 });
  await page.mouse.move(cx + 3, cy + 1, { steps: 3 });
  await page.mouse.up();
  await page.waitForTimeout(1000);

  const urlAfter = page.url();
  console.log(name, "before:", urlBefore, "after:", urlAfter, urlAfter !== urlBefore ? "NAVIGATED" : "DID NOT NAVIGATE");
