// Lightweight drag-to-scroll for desktop mouse users (touch/trackpad already
// get real native scrolling from `overflow-x-auto` + `snap-x` with no JS at
// all). Only counts as a "drag" past a real pixel threshold, and when it
// does, the click that would otherwise follow (and navigate a card's Link)
// is swallowed once — same guard GameCoverCarousel.tsx uses for its own
// momentum drag, just without the velocity/spring machinery this static
// catalogue row doesn't need.
//
// FIXED 2026-09-20 (owner-reported: no carousel card was clickable, on
// either the marketing or portal page). Root cause, confirmed with a real
// Playwright mouse.move/down/move/up sequence carrying only ~2-4px of
// jitter between mousedown and mouseup — the same jitter a real hand
// produces on a perfectly normal click, which a scripted `.click()` never
// reproduces (that's why this looked fine in a quick synthetic check):
//   1. `DRAG_THRESHOLD` was 3px — smaller than typical mouse/trackpad
//      jitter, so `moved` flipped true on almost every real click, not
//      just real drags.
//   2. `setPointerCapture` was called unconditionally in `onPointerDown`,
//      before any movement was observed at all.
// Once `moved` was (wrongly) true, `onPointerUp` installed a *capturing*
// one-time `click` listener on the track that called
// `preventDefault()`/`stopPropagation()` — which fires before the click
// ever reaches the nested `<Link>`, killing navigation. Fixed by (a)
// raising the threshold to a distance no ordinary click jitter reaches,
// and (b) deferring `setPointerCapture` until real movement past that
// threshold is observed, so a plain click never triggers capture — or the
// click-swallowing listener — at all.
const DRAG_THRESHOLD = 8;
const drag = useRef<{ startX: number; startScroll: number; moved: boolean; captured: boolean } | null>(null);

function onPointerDown(e: React.PointerEvent<HTMLDivElement>) {
  if (e.pointerType === "touch") return;
  const track = trackRef.current;
  if (!track) return;
  drag.current = { startX: e.clientX, startScroll: track.scrollLeft, moved: false, captured: false };
}
function onPointerMove(e: React.PointerEvent<HTMLDivElement>) {
  const st = drag.current;
  const track = trackRef.current;
  if (!st || !track) return;
  const dx = e.clientX - st.startX;
  if (!st.moved && Math.abs(dx) > DRAG_THRESHOLD) {
    st.moved = true;
    if (!st.captured) {
      track.setPointerCapture(e.pointerId);
      st.captured = true;
    }
  }
  if (st.moved) track.scrollLeft = st.startScroll - dx;
}
function onPointerUp(e: React.PointerEvent<HTMLDivElement>) {
  const st = drag.current;
  const track = trackRef.current;
  if (st?.moved && track) {
    const stop = (ev: Event) => {
      ev.preventDefault();
      ev.stopPropagation();
    };
    track.addEventListener("click", stop, { capture: true, once: true });
  }
  if (st?.captured && track) track.releasePointerCapture?.(e.pointerId);
  drag.current = null;
}

