"use client";

import { useEffect, useState, useTransition, useRef, useCallback } from "react";
import {
  getWhatsNew,
  markAnnouncementSeen,
  type WhatsNewEntry,
} from "@/lib/actions-announcements";
import { renderMarkdown } from "@/lib/blog";
import { GameCoverTile } from "@/components/customer/GameCoverTile";
import { GAME_DISPLAY, type GameFamily } from "@/lib/games";

const FILTERS = [
  { value: "", label: "All" },
  { value: "GAME", label: "Game Servers" },
  { value: "VPS", label: "VPS" },
  { value: "HOSTING", label: "Hosting" },
  { value: "MAIL", label: "Mail" },
];

/**
 * Full "What's New" feed: all published announcements in a timeline layout.
 * Unseen ones get a "New" badge. When an unseen announcement scrolls into
 * view (or is present on initial render), it is marked as seen after a short
 * delay so the badge lingers long enough to be noticed.
 */
export function WhatsNew() {
  const [entries, setEntries] = useState<WhatsNewEntry[]>([]);
  const [filter, setFilter] = useState("");
  const [loading, setLoading] = useState(true);
  const [, startTransition] = useTransition();

  const load = useCallback((serviceFilter: string) => {
    setLoading(true);
    getWhatsNew(serviceFilter || undefined)
      .then(setEntries)
      .catch(() => setEntries([]))
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => {
    load(filter);
  }, [filter, load]);

  function handleFilterChange(val: string) {
    setFilter(val);
  }

  /** Mark an announcement as seen (optimistic local update + server write). */
  function handleSeen(id: string) {
    setEntries((prev) =>
      prev.map((e) => (e.id === id ? { ...e, seen: true } : e)),
    );
    startTransition(async () => {
      try {
        await markAnnouncementSeen(id);
      } catch {
        /* best-effort */
      }
    });
  }

  return (
    <div className="space-y-6">
      {/* Filter tabs */}
      <div className="flex flex-wrap gap-2">
        {FILTERS.map((f) => (
          <button
            key={f.value}
            onClick={() => handleFilterChange(f.value)}
            className={`rounded-lg border px-3 py-1.5 text-sm font-medium transition-colors ${
              filter === f.value
                ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
                : "border-white/10 bg-white/[0.03] text-slate-400 hover:border-white/20 hover:text-slate-200"
            }`}
          >
            {f.label}
          </button>
        ))}
      </div>

      {/* Content */}
      {loading ? (
        <div className="py-12 text-center text-sm text-slate-500">
          Loading...
        </div>
      ) : entries.length === 0 ? (
        <div className="card flex flex-col items-center justify-center py-14 text-center">
          <div className="mb-4 rounded-2xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/15 to-brand-500/15 p-4">
            <svg
              width="28"
              height="28"
              viewBox="0 0 24 24"
              fill="none"
              stroke="#8a70fb"
              strokeWidth="1.5"
            >
              <path d="M11 3l1.8 4.9L17.7 9.7l-4.9 1.8L11 16.4l-1.8-4.9L4.3 9.7l4.9-1.8zM18 14.5l.85 2.15L21 17.5l-2.15.85L18 20.5l-.85-2.15L15 17.5l2.15-.85z" />
            </svg>
          </div>
          <p className="text-sm font-medium text-white">No updates yet</p>
          <p className="mt-1 text-sm text-slate-400">
            We&apos;ll post here when there&apos;s something new.
          </p>
        </div>
      ) : (
        <div className="space-y-4">
          {entries.map((entry) => (
            <AnnouncementCard
              key={entry.id}
              entry={entry}
              onSeen={handleSeen}
            />
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState, useTransition, useCallback } from "react";
import { createPortal } from "react-dom";
import {
  getUnseenAnnouncements,
  markAnnouncementSeen,
} from "@/lib/actions-announcements";
import { renderMarkdown } from "@/lib/blog";
import { GameCoverTile } from "@/components/customer/GameCoverTile";
import { GAME_DISPLAY, type GameFamily } from "@/lib/games";

type Announcement = {
  id: string;
  title: string;
  body: string;
  screenshotUrl: string | null;
  serviceTypes: string[];
  gameFamilies: string[];
  publishedAt: Date | null;
};

/**
 * Shows unseen update announcements as a modal popup, one at a time.
 * Mounted inside the dashboard layout so it only fires for authenticated users.
 * Uses createPortal to escape any transformed ancestors (same fix as
 * HeardAboutUsPrompt.tsx).
 */
export function AnnouncementPopup() {
  const [queue, setQueue] = useState<Announcement[]>([]);
  const [loaded, setLoaded] = useState(false);
  const [, startTransition] = useTransition();

  useEffect(() => {
    let cancelled = false;
    getUnseenAnnouncements()
      .then((items) => {
        if (!cancelled) {
          setQueue(items);
          setLoaded(true);
        }
      })
      .catch(() => {
        // Soft-fail: never block the portal over a failed announcement fetch.
        if (!cancelled) setLoaded(true);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const dismiss = useCallback(() => {
    const current = queue[0];
    if (!current) return;
    // Remove from queue optimistically.
    setQueue((prev) => prev.slice(1));
    // Persist the seen record in the background.
    startTransition(async () => {
      try {
        await markAnnouncementSeen(current.id);
      } catch {
        /* best-effort */
      }
    });
  }, [queue]);

  // Nothing to show (not loaded, or no unseen announcements).
  if (!loaded || queue.length === 0) return null;
  if (typeof document === "undefined") return null;

  const current = queue[0];

  return createPortal(
    <div
      className="fixed inset-0 z-[70] flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm"
      role="dialog"
      aria-modal="true"
      aria-labelledby="announcement-title"
      onClick={dismiss}
    >

