"use client";

import { useRef } from "react";
import { IconArrow } from "./icons";

/**
 * A curated mod rail rendered as a real sliding carousel — item 6 of the
 * 2026-09-20 NxLabs overhaul. Reuses the exact scroll-snap-track +
 * arrow-button + pointer-drag mechanism GameCatalogueCarousel.tsx already
 * shipped tonight for the game catalogue (this codebase's only other
 * carousel — checked before writing a second one). No search box here:
 * unlike the ~17 game families search made sense over, a single curated
 * rail is only 8-12 mods, and the real "see everything" escape hatch is the
 * "View more" link its caller renders next to the section heading, into the
 * full searchable/paginated StoreBrowser grid scoped to the same sort.
 *
 * CORRECTED 2026-09-20: this originally imported `ModCard` and rendered it
 * directly here, on the theory that ModSummary is plain serializable data
 * so no server/client split was needed (unlike GameCatalogueGrid/Carousel).
 * That missed that `ModCard` conditionally renders `GameBadge`, an ASYNC
 * SERVER COMPONENT (lib/game-poster-color.ts's real-pixel accent-color
 * sampling uses the server-only `sharp` package) — importing it into this
 * "use client" file pulled `sharp`'s `node:child_process`/`node:crypto`
 * imports into the browser bundle and broke the production build entirely.
 * Fixed the correct way: this component only owns the carousel SHELL
 * (scroll-snap track, arrows, drag-to-scroll); the caller (a Server
 * Component page) renders each `<ModCard>` itself and hands the already-
 * rendered elements in via `items`, exactly the split GameCatalogueGrid/
 * Carousel already used for the same reason.
 */
function prefersReducedMotion() {
  return typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
}

export function ModCarouselRow({
  items,
}: {
  items: { key: string; node: React.ReactNode }[];
}) {
  const trackRef = useRef<HTMLDivElement>(null);

  function scrollByCard(dir: 1 | -1) {
    const track = trackRef.current;
    if (!track) return;
    const card = track.querySelector<HTMLElement>("[data-card]");
    const step = card ? card.offsetWidth + 20 /* gap-5 */ : track.clientWidth * 0.8;
    track.scrollBy({ left: dir * step, behavior: prefersReducedMotion() ? "auto" : "smooth" });
  }

  // Same desktop-mouse drag-to-scroll as GameCatalogueCarousel — touch/

