async function attempt(page, findFn, urlPattern, label) {
  await page.goto(BASE + "/mods", { waitUntil: "networkidle", timeout: 60000 });
  const gotIt = page.getByText("Got it", { exact: true });
  if (await gotIt.count()) await gotIt.first().click().catch(() => {});
  await page.waitForTimeout(300);
  const idx = await page.evaluate(findFn);
  if (idx < 0) { console.log(label, "no card found"); return; }
  const card = page.locator("[data-card]").nth(idx);
  await card.scrollIntoViewIfNeeded();
  await page.waitForTimeout(250);
  const box = await card.boundingBox();
  const cx = box.x + box.width / 2, cy = box.y + box.height / 2;
  await page.mouse.move(cx, cy);
  await page.mouse.down();
  await page.mouse.move(cx + 2, cy + 1, { steps: 3 });
  await page.mouse.up();
  try {
    await page.waitForURL(urlPattern, { timeout: 20000 });
    console.log(label, "PASS ->", page.url());
  } catch {
    console.log(label, "FAIL, still at", page.url());
  }
}

const findGameCard = () => {
  const cards = Array.from(document.querySelectorAll("[data-card]"));
  return cards.findIndex((c) => c.tagName === "A" && /^\/mods\/games\//.test(c.getAttribute("href") || ""));
};
const findModCard = () => {
  const cards = Array.from(document.querySelectorAll("[data-card]"));
  return cards.findIndex((c) => {
    const a = c.querySelector("a");
    return a && /^\/mods\/[a-z0-9]+\/[a-z0-9-]+$/.test(a.getAttribute("href") || "");
  });
};

const ctx = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
